import os
import shutil
import urllib.request
from pathlib import Path

# Paths
BASE_DIR = Path(__file__).resolve().parent.parent / "dataset/edge_cases"
SRC_DIR = Path(r"C:\Users\Debangshu Ghosh\.gemini\antigravity\brain\3d32ad16-df30-421d-ba43-d56db2a7aa05")

# Images generated by AI
generated_images = {
    "low_light": "edge_low_light_1_1776709052378.png",
    "crowded_paths": "edge_crowded_1_1776709082421.png",
    "glass_reflective": "edge_glass_1_1776709110084.png"
}

# Fallback URLs for the ones that hit rate limits
fallback_urls = {
    "stairs_curb": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/df/Concrete_stairs.jpg/800px-Concrete_stairs.jpg",
    "cluttered_indoor": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Messy_room.jpg/800px-Messy_room.jpg"
}

def setup_dataset():
    BASE_DIR.mkdir(parents=True, exist_ok=True)
    
    # 1. Copy generated images
    for category, filename in generated_images.items():
        cat_dir = BASE_DIR / category
        cat_dir.mkdir(exist_ok=True)
        
        src_path = SRC_DIR / filename
        dest_path = cat_dir / f"{category}_1.png"
        
        if src_path.exists():
            shutil.copy2(src_path, dest_path)
            print(f"Copied {category} image.")
        else:
            print(f"Warning: {src_path} not found.")

    # 2. Download fallback images
    for category, url in fallback_urls.items():
        cat_dir = BASE_DIR / category
        cat_dir.mkdir(exist_ok=True)
        
        dest_path = cat_dir / f"{category}_1.jpg"
        try:
            req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
            with urllib.request.urlopen(req) as response, open(dest_path, 'wb') as out_file:
                shutil.copyfileobj(response, out_file)
            print(f"Downloaded {category} image.")
        except Exception as e:
            print(f"Failed to download {category}: {e}")

if __name__ == "__main__":
    setup_dataset()
    print("Dataset setup complete.")
